import torch, b200probe as bp
SRC = r'''
#define CH_ %d
#define ST_ %d
#define CS_ %d
__device__ __forceinline__ unsigned sa(const void* p){return (unsigned)__cvta_generic_to_shared(p);}
__device__ __forceinline__ void wait_par(unsigned b, unsigned ph){
  asm volatile("{\n .reg .pred p;\n W: mbarrier.try_wait.parity.acquire.cluster.shared::cta.b64 p, [%%0], %%1;\n @!p bra W;\n}" :: "r"(b),"r"(ph):"memory");}
extern "C" __global__ void __cluster_dims__(CS_,1,1) __launch_bounds__(32) bulk(const char* buf, long long bufsz, long long per_cta){
  extern __shared__ __align__(128) char smem[];
  __shared__ __align__(8) unsigned long long full[ST_], empty[ST_];
  unsigned rank=0; asm volatile("mov.u32 %%0, %%cluster_ctarank;":"=r"(rank));
  unsigned cid = blockIdx.x / CS_;
  int lane = threadIdx.x;
  if(lane==0){ for(int s=0;s<ST_;++s){ asm volatile("mbarrier.init.shared::cta.b64 [%%0], 1;"::"r"(sa(&full[s])));
      asm volatile("mbarrier.init.shared::cta.b64 [%%0], %%1;"::"r"(sa(&empty[s])),"r"(CS_));}
    asm volatile("fence.mbarrier_init.release.cluster;":::"memory");
    for(int s=0;s<ST_;++s) asm volatile("mbarrier.arrive.expect_tx.shared::cta.b64 _, [%%0], %%1;"::"r"(sa(&full[s])),"r"(CH_):"memory");
  }
  asm volatile("barrier.cluster.arrive.release.aligned; barrier.cluster.wait.acquire.aligned;":::"memory");
  if(lane==0){
    long long nch = per_cta / CH_;
    const char* base = buf;
    long long start = (long long)cid * per_cta;
    auto issue=[&](long long i){
      if((int)(i % CS_)!=(int)rank) return;
      int s = i % ST_;
      if(i>=ST_) wait_par(sa(&empty[s]), (unsigned)(((i-ST_)/ST_)&1));
      const char* src = base + ((start + i*CH_) % bufsz);
#if CS_==1
      asm volatile("cp.async.bulk.shared::cta.global.mbarrier::complete_tx::bytes [%%0], [%%1], %%2, [%%3];"
        :: "r"(sa(smem+s*CH_)),"l"(src),"r"(CH_),"r"(sa(&full[s])):"memory");
#else
      unsigned short mask=(1u<<CS_)-1;
      asm volatile("cp.async.bulk.shared::cluster.global.mbarrier::complete_tx::bytes.multicast::cluster [%%0], [%%1], %%2, [%%3], %%4;"
        :: "r"(sa(smem+s*CH_)),"l"(src),"r"(CH_),"r"(sa(&full[s])),"h"(mask):"memory");
#endif
    };
    for(long long i=0;i<ST_ && i<nch;++i) issue(i);
    for(long long i=0;i<nch;++i){
      int s=i%ST_;
      wait_par(sa(&full[s]), (unsigned)((i/ST_)&1));
      if(i+ST_<nch){
        asm volatile("mbarrier.arrive.expect_tx.shared::cta.b64 _, [%%0], %%1;"::"r"(sa(&full[s])),"r"(CH_):"memory");
        unsigned tgt=(unsigned)((i+ST_)%CS_), ra;
        asm volatile("mapa.shared::cluster.u32 %%0, %%1, %%2;":"=r"(ra):"r"(sa(&empty[s])),"r"(tgt));
        asm volatile("mbarrier.arrive.release.cluster.shared::cluster.b64 _, [%%0];"::"r"(ra):"memory");
        issue(i+ST_);
      }
    }
  }
  __syncwarp();
  asm volatile("barrier.cluster.arrive.release.aligned; barrier.cluster.wait.acquire.aligned;":::"memory");
}
extern "C" __global__ void __launch_bounds__(256) ldgsts(const char* buf, long long bufsz, long long per_cta){
  extern __shared__ __align__(128) char smem[];
  long long start=(long long)blockIdx.x*per_cta;
  long long nch=per_cta/CH_;
  for(long long i=0;i<nch;++i){
    int s=i%ST_;
    #pragma unroll
    for(int u=0;u<CH_/(256*16);++u){
      int o=u*4096+threadIdx.x*16;
      const char* src=buf+((start+i*CH_+o)%bufsz);
      asm volatile("cp.async.cg.shared.global [%%0], [%%1], 16;"::"r"(sa(smem+s*CH_+o)),"l"(src):"memory");
    }
    asm volatile("cp.async.commit_group;":::"memory");
    asm volatile("cp.async.wait_group %%0;"::"n"(ST_-1):"memory");
  }
  asm volatile("cp.async.wait_group 0;":::"memory");
}
'''
buf = torch.ones(2*1024**3//2, dtype=torch.float16, device='cuda')
cache={}
def get(CH,ST,CS,name):
    k=(CH,ST,CS,name)
    if k not in cache:
        kk=bp.cuda_kernel(SRC%(CH,ST,CS),name); kk.set_smem(CH*ST); cache[k]=kk
    return cache[k]
def run(name,CH,ST,CS,grid,per_cta,bufsz,cold=False,reps=3):
    k=get(CH,ST,CS,name); thr=32 if name=='bulk' else 256
    ts=[]
    for r in range(reps+1):
        if cold: bp.flush_l2()
        else: k((grid,),(thr,),buf,bp.i64(bufsz),bp.i64(per_cta),smem=CH*ST)
        e0=torch.cuda.Event(True);e1=torch.cuda.Event(True)
        e0.record(); k((grid,),(thr,),buf,bp.i64(bufsz),bp.i64(per_cta),smem=CH*ST); e1.record(); torch.cuda.synchronize()
        if r: ts.append(e0.elapsed_time(e1)*1e3)
    t=min(ts)
    nsm=min(grid,148) 
    print(f"{name:6s} CH={CH//1024:3d}K ST={ST} CS={CS} grid={grid:4d} per_cta={per_cta>>20}MB {'cold' if cold else 'L2  '} t={t:8.1f}us  per-CTA {per_cta/t/1e3:6.1f} GB/s  agg ingress {grid*per_cta/t/1e6:6.2f} TB/s  L2-read {grid*per_cta/CS/t/1e6:6.2f} TB/s")
L2=32<<20
MB=1<<20
for (CH,ST) in [(32768,4),(16384,8),(32768,6)]:
    run('bulk',CH,ST,1,148,8*MB,L2)
for g in [74,37,16]:
    run('bulk',32768,4,1,g,8*MB,L2)
run('bulk',16384,4,1,296,4*MB,L2)
run('bulk',8192,4,1,592,2*MB,L2)
for (CH,ST) in [(32768,4),(16384,8)]:
    run('ldgsts',CH,ST,1,148,8*MB,L2)
run('ldgsts',16384,4,1,296,4*MB,L2)
for CS in [2,4]:
    run('bulk',32768,4,CS,148,8*MB,L2)
    run('bulk',16384,8,CS,148,8*MB,L2)
run('bulk',32768,4,1,148,4*MB,1<<40,cold=True)
run('bulk',16384,4,1,296,2*MB,1<<40,cold=True)
run('ldgsts',32768,4,1,148,4*MB,1<<40,cold=True)

