extern "C" __global__ void __cluster_dims__(CS_,1,1) __launch_bounds__(32) bulk(const char* buf, long long bufsz, long long per_cta){
  extern __shared__ __align__(128) char smem[];
  __shared__ __align__(8) unsigned long long full[ST_], empty[ST_];
  unsigned rank=0; asm volatile("mov.u32 %0, %%cluster_ctarank;":"=r"(rank));
  unsigned cid = blockIdx.x / CS_;
  if(threadIdx.x==0){ for(int s=0;s<ST_;++s){ asm volatile("mbarrier.init.shared::cta.b64 [%0], 1;"::"r"(sa(&full[s])));
      asm volatile("mbarrier.init.shared::cta.b64 [%0], %1;"::"r"(sa(&empty[s])),"r"(CS_));}
    asm volatile("fence.mbarrier_init.release.cluster;":::"memory");
    for(int s=0;s<ST_;++s) asm volatile("mbarrier.arrive.expect_tx.shared::cta.b64 _, [%0], %1;"::"r"(sa(&full[s])),"r"(CH_):"memory");
  }
  asm volatile("barrier.cluster.arrive.release.aligned; barrier.cluster.wait.acquire.aligned;":::"memory");
  if(threadIdx.x==0){
    long long nch = per_cta / CH_, start = (long long)cid * per_cta;
    auto issue=[&](long long i){
      if((int)(i % CS_)!=(int)rank) return;
      int s = i % ST_;
      if(i>=ST_) wait_par(sa(&empty[s]), (unsigned)(((i-ST_)/ST_)&1));
      long long off = start + i*CH_; if(off>=bufsz) off%=bufsz;
      unsigned short mask=(1u<<CS_)-1;
      asm volatile("cp.async.bulk.shared::cluster.global.mbarrier::complete_tx::bytes.multicast::cluster [%0], [%1], %2, [%3], %4;"
        :: "r"(sa(smem+s*CH_)),"l"(buf+off),"r"(CH_),"r"(sa(&full[s])),"h"(mask):"memory");
    };
    for(long long i=0;i<ST_ && i<nch;++i) issue(i);
    for(long long i=0;i<nch;++i){
      int s=i%ST_;
      wait_par(sa(&full[s]), (unsigned)((i/ST_)&1));
      if(i+ST_<nch){
        asm volatile("mbarrier.arrive.expect_tx.shared::cta.b64 _, [%0], %1;"::"r"(sa(&full[s])),"r"(CH_):"memory");
        unsigned tgt=(unsigned)((i+ST_)%CS_), ra;
        asm volatile("mapa.shared::cluster.u32 %0, %1, %2;":"=r"(ra):"r"(sa(&empty[s])),"r"(tgt));
        asm volatile("mbarrier.arrive.@SEM.cluster.shared::cluster.b64 _, [%0];"::"r"(ra):"memory");
        issue(i+ST_);
      }
    }
  }
  __syncwarp();
  asm volatile("barrier.cluster.arrive.release.aligned; barrier.cluster.wait.acquire.aligned;":::"memory");
}
