                                                   reinterpret_cast<__half*>(C), M);
}

// Returns 0 when the GEMM was launched; nonzero (nothing launched) means the caller must fall back.
extern "C" int launch_lt_tile(const void* A, const void* B, void* C, int M, int want_tile, cudaStream_t stream) {
  if (!g_lt && cublasLtCreate(&g_lt) != CUBLAS_STATUS_SUCCESS) { g_lt = nullptr; return 1; }
  const long long key = (static_cast<long long>(M) << 20) | want_tile;
  auto it = g_plans.find(key);
  if (it == g_plans.end()) it = g_plans.emplace(key, make_plan(M, want_tile)).first;
  const LtPlan& p = it->second;
  if (!p.ok) return 2;
  const float alpha = 1.f, beta = 0.f;
  return cublasLtMatmul(g_lt, p.op, &alpha, B, p.la, A, p.lb, &beta, C, p.lc, C, p.lc, &p.algo, nullptr, 0, stream) ==
                 CUBLAS_STATUS_SUCCESS
             ? 0
             : 3;
}

// Mid-M path: CUTLASS sm100 1-SM tcgen05 GEMM, BK=64, with a (1, CN) cluster so the A tile is TMA-multicast to the
// CN CTAs that share it (each issues 1/CN of A). Probe E3: per-SM operand ingress through a single TMA producer
// is ~86-110 GB/s, so cutting the bytes each SM issues is the lever. fp16 in, fp32 accumulate, fp16 out; no C source.
#pragma once
#include <cuda_runtime.h>
#include "cutlass/cutlass.h"
#include "cute/tensor.hpp"
#include "cutlass/gemm/dispatch_policy.hpp"
#include "cutlass/gemm/collective/collective_builder.hpp"
#include "cutlass/epilogue/collective/collective_builder.hpp"
#include "cutlass/gemm/device/gemm_universal_adapter.h"
#include "cutlass/gemm/kernel/gemm_universal.hpp"
#include "cutlass/util/packed_stride.hpp"

namespace mid {
using namespace cute;

template <int TM, int TN, int TK, int CN>
struct Tile1Sm {
  using EA = cutlass::half_t;
  using LA = cutlass::layout::RowMajor;      // A [M,K], K innermost
  using EB = cutlass::half_t;
  using LB = cutlass::layout::ColumnMajor;   // B [N,K] row-major = K x N column-major
  using ED = cutlass::half_t;
  using LD = cutlass::layout::RowMajor;
  using Acc = float;
  using MmaTile = Shape<Int<TM>, Int<TN>, Int<TK>>;
  using Cluster = Shape<_1, Int<CN>, _1>;
  using Epi = typename cutlass::epilogue::collective::CollectiveBuilder<
      cutlass::arch::Sm100, cutlass::arch::OpClassTensorOp, MmaTile, Cluster,
      cutlass::epilogue::collective::EpilogueTileAuto, Acc, Acc,
      void, LD, 8, ED, LD, 8, cutlass::epilogue::TmaWarpSpecialized1Sm>::CollectiveOp;
  using Main = typename cutlass::gemm::collective::CollectiveBuilder<
      cutlass::arch::Sm100, cutlass::arch::OpClassTensorOp, EA, LA, 8, EB, LB, 8, Acc, MmaTile, Cluster,
      cutlass::gemm::collective::StageCountAutoCarveout<static_cast<int>(sizeof(typename Epi::SharedStorage))>,
      cutlass::gemm::KernelTmaWarpSpecialized1SmSm100>::CollectiveOp;
  using Kern = cutlass::gemm::kernel::GemmUniversal<Shape<int, int, int, int>, Main, Epi, void>;
  using Gemm = cutlass::gemm::device::GemmUniversalAdapter<Kern>;

  // Returns 0 when the GEMM was launched; nonzero (nothing launched) means the caller must fall back.
  static int launch(const void* A, const void* B, void* D, int M, cudaStream_t stream) {
    constexpr int N = 5120, K = 2048;
    static int sm_count = cutlass::KernelHardwareInfo::query_device_multiprocessor_count(0);
    int dev = 0;
    cudaGetDevice(&dev);
    auto sA = cutlass::make_cute_packed_stride(typename Kern::StrideA{}, {M, K, 1});
    auto sB = cutlass::make_cute_packed_stride(typename Kern::StrideB{}, {N, K, 1});
    auto sD = cutlass::make_cute_packed_stride(typename Kern::StrideD{}, {M, N, 1});
    cutlass::KernelHardwareInfo hw;
    hw.device_id = dev;
    hw.sm_count = sm_count;
    typename Gemm::Arguments args{cutlass::gemm::GemmUniversalMode::kGemm, {M, N, K, 1},
                                  {static_cast<const EA*>(A), sA, static_cast<const EB*>(B), sB},
                                  {{1.0f, 0.0f}, nullptr, sD, static_cast<ED*>(D), sD}, hw};
    args.scheduler.max_swizzle_size = 0;
    args.scheduler.raster_order = decltype(args.scheduler.raster_order)::AlongN;
    if (Gemm::get_workspace_size(args) != 0) return 4;
    static Gemm gemm;
    if (gemm.can_implement(args) != cutlass::Status::kSuccess) return 1;
    if (gemm.initialize(args, nullptr, stream) != cutlass::Status::kSuccess) return 2;
    if (gemm.run(stream) != cutlass::Status::kSuccess) return 3;
    return 0;
  }
};
}  // namespace mid

