  using Main = typename cutlass::gemm::collective::CollectiveBuilder<
      cutlass::arch::Sm100, cutlass::arch::OpClassTensorOp, EA, LA, 8, EB, LB, 8, Acc, MmaTile, Cluster,
      cutlass::gemm::collective::StageCountAutoCarveout<static_cast<int>(sizeof(typename Epi::SharedStorage))>,
      MainS>::CollectiveOp;
  using Kern = cutlass::gemm::kernel::GemmUniversal<Shape<int, int, int, int>, Main, Epi, void>;
  using Gemm = cutlass::gemm::device::GemmUniversalAdapter<Kern>;

  // Returns 0 when the GEMM was launched; nonzero (nothing launched) means the caller must fall back.
  static int launch(const void* A, const void* B, void* D, int M, cudaStream_t stream) {
    constexpr int N = 5120, K = 2048;
    static int sm_count = cutlass::KernelHardwareInfo::query_device_multiprocessor_count(0);
    int dev = 0;
    cudaGetDevice(&dev);
    auto sA = cutlass::make_cute_packed_stride(typename Kern::StrideA{}, {M, K, 1});
    auto sB = cutlass::make_cute_packed_stride(typename Kern::StrideB{}, {N, K, 1});
    auto sD = cutlass::make_cute_packed_stride(typename Kern::StrideD{}, {M, N, 1});
    cutlass::KernelHardwareInfo hw;
    hw.device_id = dev;
    hw.sm_count = sm_count;
    typename Gemm::Arguments args{cutlass::gemm::GemmUniversalMode::kGemm, {M, N, K, 1},
                                  {static_cast<const EA*>(A), sA, static_cast<const EB*>(B), sB},
                                  {{1.0f, 0.0f}, nullptr, sD, static_cast<ED*>(D), sD}, hw};
    args.scheduler.max_swizzle_size = 0;
    args.scheduler.raster_order = decltype(args.scheduler.raster_order)::AlongN;
    if (Gemm::get_workspace_size(args) != 0) return 4;
    static Gemm gemm;
    if (gemm.can_implement(args) != cutlass::Status::kSuccess) return 1;
    if (gemm.initialize(args, nullptr, stream) != cutlass::Status::kSuccess) return 2;
    if (gemm.run(stream) != cutlass::Status::kSuccess) return 3;
    return 0;
  }
