  return mid::Tile<128, 112, 64, 1>::launch(A, B, D, M, stream);
}

// 256x160x64 2-SM tile (cluster 2x1): 2 x 32 = 64 pairs = 128 CTAs at M=492 (one wave).
#include "cutlass_tile.cuh"

extern "C" int launch_cutlass_256x160(const void* A, const void* B, void* D, int M, cudaStream_t stream) {
  return mid::Tile<256, 160, 64, 2>::launch(A, B, D, M, stream);
}

// 256x256x64 2-SM tile (cluster 2x1): 4 x 20 = 80 pairs = 160 CTAs at M=952.
#include "cutlass_tile.cuh"

extern "C" int launch_cutlass_256x256(const void* A, const void* B, void* D, int M, cudaStream_t stream) {
  return mid::Tile<256, 256, 64, 2>::launch(A, B, D, M, stream);
}

#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAGuard.h>

extern "C" void launch_skinny_m16(const void* A, const void* B, void* C, int M, cudaStream_t stream);
extern "C" int launch_lt_tile(const void* A, const void* B, void* C, int M, int want_tile, cudaStream_t stream);
extern "C" int launch_cutlass_128x112(const void* A, const void* B, void* D, int M, cudaStream_t stream);
extern "C" int launch_cutlass_256x160(const void* A, const void* B, void* D, int M, cudaStream_t stream);
extern "C" int launch_cutlass_256x256(const void* A, const void* B, void* D, int M, cudaStream_t stream);

namespace {
constexpr int64_t N_DIM = 5120;
constexpr int64_t K_DIM = 2048;

bool aligned(const void* p, uintptr_t a) { return (reinterpret_cast<uintptr_t>(p) & (a - 1)) == 0; }

// cublasLt tile ids measured faster than cuBLAS's default pick on B200 (harness timing, probe r1).
int lt_tile_for(int64_t M) {
  if (M >= 20 && M <= 48) return 314;    // M=25: 7.85 vs 8.45 us; M=34: 8.0 vs 8.7 us
  if (M >= 150 && M <= 200) return 183;  // M=172: 9.7 vs 10.2 us
  return -1;
}
}  // namespace

// DPS entry: C = A @ B.T, A [M,2048] fp16, B [5120,2048] fp16, C [M,5120] fp16.
void run(torch::Tensor A, torch::Tensor B, torch::Tensor C) {
  TORCH_CHECK(A.is_cuda() && B.is_cuda() && C.is_cuda(), "inputs must be CUDA tensors");
  TORCH_CHECK(A.scalar_type() == torch::kHalf && B.scalar_type() == torch::kHalf && C.scalar_type() == torch::kHalf,
              "fp16 expected");
  TORCH_CHECK(A.dim() == 2 && B.dim() == 2 && C.dim() == 2, "2-D tensors expected");
  const int64_t M = A.size(0);
  TORCH_CHECK(A.size(1) == K_DIM && B.size(0) == N_DIM && B.size(1) == K_DIM && C.size(0) == M && C.size(1) == N_DIM,
              "unexpected shape");
  const at::cuda::OptionalCUDAGuard guard(A.device());
  cudaStream_t stream = at::cuda::getCurrentCUDAStream().stream();

  const bool contig = A.is_contiguous() && B.is_contiguous() && C.is_contiguous();
  if (contig && M >= 1 && M <= 16 && aligned(A.data_ptr(), 32) && aligned(B.data_ptr(), 32)) {
    launch_skinny_m16(A.data_ptr(), B.data_ptr(), C.data_ptr(), static_cast<int>(M), stream);
    return;
  }
  // Mid band: whole-wave CUTLASS tiles (E3/H17).
  const bool al16 = aligned(A.data_ptr(), 16) && aligned(B.data_ptr(), 16) && aligned(C.data_ptr(), 16);
  if (contig && al16 && M > 200 && M <= 400) {
    if (launch_cutlass_128x112(A.data_ptr(), B.data_ptr(), C.data_ptr(), static_cast<int>(M), stream) == 0) return;
  }
  if (contig && al16 && M > 400 && M <= 700) {
    if (launch_cutlass_256x160(A.data_ptr(), B.data_ptr(), C.data_ptr(), static_cast<int>(M), stream) == 0) return;
  }
  if (contig && al16 && M > 700 && M <= 1500) {
    if (launch_cutlass_256x256(A.data_ptr(), B.data_ptr(), C.data_ptr(), static_cast<int>(M), stream) == 0) return;
  }
  const int tile = lt_tile_for(M);
  if (contig && tile >= 0) {
    if (launch_lt_tile(A.data_ptr(), B.data_ptr(), C.data_ptr(), static_cast<int>(M), tile, stream) == 0) return;
  }
  at::matmul_out(C, A, B.t());
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) { m.def("run", &run, "GEMM C = A @ B.T (DPS)"); }
